import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Favicon tek bir görüntü değildir. Tarayıcıda ya da cihazda farklı bir yere hizmet eden, farklı boyutlarda bir görüntü ailesidir. En küçüğü sekme için 16'ya 16 piksel, en büyüğü Android yükleme ekranları için 512'ye 512 pikseldir.</p>\n<p>Hangi boyutun nereye gittiğini anlamak seni iki klasik arızadan kurtarır: bulanık bir sekme simgesi ve pikselli bir ana ekran simgesi. Bu kılavuz tam bir paketin her boyutunu, 16'dan 512 piksele, gezer ve her birinin ne yaptığını açıklar.</p>\n<p>Bu boyutların tamamı <a href=\"/tr/favicon-olusturucu\">favicon oluşturucu</a> aracına tek yüklemeden çıkar. Her boyutu elle dışa aktarman asla gerekmez. Paketin ne içerdiğini bilmek, eksik bir şey olmadığını doğrulamana ve her ölçekte işe yarayan bir marka tasarlamana yardımcı olur.</p>\n<h2 id=\"the-16-pixel-tab-icon\">16 piksellik sekme simgesi</h2>\n<p>16'ya 16 piksel, favicon'un doğduğu boyuttur ve çoğu kişinin en sık gördüğü boyut olmaya devam eder. Sayfa başlığının yanında tarayıcı sekmesindedir; kabaca büyük bir harfin genişliğinde bir karedir.</p>\n<p>Bu boyutta yalnızca en belirgin biçimler ayakta kalır. Tek bir harf, katı bir sembol ya da yüksek kontrastlı bir biçim net okunur. İnce çizgiler kaybolur, degradeler tek tona düzleşir ve küçük metin gürültü olur. Önce bu boyut için tasarla; geri kalan kendiliğinden gelir.</p>\n<p>Tüm tarayıcılar sekme çubuğunda 16 piksellik simgeyi kullanır ve çoğu yer imi menülerinde ve geçmiş listelerinde de kullanır. Pakette en çok çalışan boyuttur; düzenli bir ziyaretçi tarafından günde yüzlerce kez görülür.</p>\n<p>Simgeni incelerken başka bir şeyden önce 16 piksellik önizlemeye bak. Marka orada tanınıyorsa her yerde tanınır. Orada bulanık görünüyorsa hiçbir büyük boyut onu kurtaramaz.</p>\n<h2 id=\"the-32-pixel-retina-tab-icon\">32 piksellik retina sekme simgesi</h2>\n<p>32'ye 32 piksel, sekme simgesinin retina sürümüdür. Yüksek yoğunluklu ekranlar aynı alana iki kat fiziksel piksel sığdırır; bu yüzden tarayıcılar modern dizüstü ve masaüstü bilgisayarlarda sekme markasının keskin kalması için 32 piksellik simgeyi ister.</p>\n<p>Standart bir ekranda 32 piksellik simge 16'ya küçülür ve daha küçük dosyayla aynı görünür. Retina ekranda tam keskinliğiyle gösterilir; kenarlar yumuşak yerine tanımlı görünür. Fark incedir ama yan yana karşılaştırıldığında fark edilir.</p>\n<p>ICO kapsayıcısı 16 ve 32 piksellik sürümleri saklar; bu yüzden tarayıcı çalıştığı ekran için uygun olanı seçer. Aralarında seçim yapman ya da ayrı sunman gerekmez.</p>\n<p>16 piksel için tasarlanmış bir marka 32'de iyi çalışır, çünkü büyük boyut yalnızca keskinlik ekler. Tersi doğru değildir: anlaşılması için 32 piksel ayrıntı gerektiren bir marka 16'ya sıkıştırıldığında dağılır.</p>\n<h2 id=\"the-48-pixel-shortcut-icon\">48 piksellik kısayol simgesi</h2>\n<p>48'e 48 piksel, Windows'un masaüstü kısayolları ve görev çubuğu sabitlemeleri için kullandığı boyuttur. Biri siteni masaüstüne sürüklediğinde ya da görev çubuğuna sabitlediğinde 48 piksellik simge görünür.</p>\n<p>Ayrıca bazı tarayıcı yer imi yöneticilerinde ve eski tarayıcıların adres çubuğunda görünür. Ara bir boyuttur: sekme simgesinden biraz daha fazla ayrıntı gösterecek kadar büyük ama sadeliğin kazandığı kadar küçük.</p>\n<p>ICO dosyası 48 piksellik boyutu küçüklerin yanında içerir; bu yüzden masaüstü kısayolları gerilmiş 16 piksellik bir dosya yerine uygun bir simge alır. Bu boyuta gerilmiş bir simge yumuşak ve profesyonellikten uzak görünür; bu yüzden özel boyut vardır.</p>\n<p>Çoğu site bu boyutu asla düşünmez ve çoğu ziyaretçi onu bilinçli olarak asla fark etmez. Birinin siteni görev çubuğuna sabitleyip her sabah diğer uygulamalarının yanında gördüğü gün önemli olur.</p>\n<h2 id=\"the-64-and-96-pixel-sizes\">64 ve 96 piksellik boyutlar</h2>\n<p>64 ve 96 piksellik simgeler ara bağlamları kapsar: daha büyük yer imi karoları, tarayıcının yeni sekme sayfaları ve bazı uzantı arayüzleri. Tarayıcının sekmelerden daha fazla ama ana ekrandan daha az alanı olduğunda görünen boyutlardır.</p>\n<p>64 pikselde bir logo 16'dan biraz daha fazla karakter taşıyabilir. İki tonlu bir marka ya da arka plan biçimli sade bir sembol iyi okunur. 96 pikselde simge sekme markasından çok küçük bir uygulama karosu gibi görünmeye başlar.</p>\n<p>Bu boyutlar da ICO kapsayıcısının içinde yaşar; bu yüzden fazladan hiçbir şeye mal olmazlar. Tarayıcı ihtiyaç duyduğuna en yakın boyutu seçer ve geri kalanı ölçekler; bu kenarları temiz tutar.</p>\n<p>Tasarım yaparken bu boyutları nadiren düşünmen gerekir, çünkü 16 ve 180'de işe yarayan her şey 64 ve 96'da da işe yarar. Boşlukları doldurmak için vardırlar; böylece hiçbir bağlam asla kötü ölçeklenmiş bir simge almaz.</p>\n<h2 id=\"the-180-pixel-apple-touch-icon\">180 piksellik Apple Touch Icon</h2>\n<p>180'e 180 piksel, bir iPhone ya da iPad kullanıcısı siteni ana ekrana eklediğinde kullanılan Apple Touch Icon'dur. Simgenin sekme işareti olarak değil, tasarım olarak değerlendirilecek kadar büyük gösterildiği ilk boyuttur.</p>\n<p>Apple bu simgede şeffaflığı yok sayar ve şeffaf bölgeleri siyahla doldurur. Şeffaf arka planlı bir logo hata gibi görünen siyah köşeler alır; bu yüzden katı bir arka plan burada standart seçimdir. Tasarımın arkasında marka renginde bir kare güvenli ve çekici seçimdir.</p>\n<p>Apple ayrıca ana ekran simgelerine kendi yuvarlak köşe maskesini uygular; bu yüzden 180 piksellik görüntünün köşeleri sistem biçiminin arkasında gizlenir. Bunu aklında tutarak tasarla: önemli ayrıntıları köşelerden uzak tut, çünkü maske onları kırpar.</p>\n<p>Apple Touch Icon, ICO kapsayıcısından ayrı bir PNG dosyasıdır. HTML parçasından özel bir bağlantı etiketiyle bağlanır ve tarayıcı onu yalnızca kullanıcı siteyi ana ekrana eklediğinde indirir.</p>\n<h2 id=\"the-192-pixel-android-icon\">192 piksellik Android simgesi</h2>\n<p>192'ye 192 piksel, web manifestosunda listelenen Android ana ekran simgesidir. Bir Android kullanıcısı siteni ana ekrana eklediğinde uygulamalarının yanında görünen simge budur.</p>\n<p>Android, cihaza ve başlatıcıya göre simgeye maske uygular; bu yüzden güvenli bölge önemlidir. Markayı etrafında dolguyla ortada tut, çünkü bir başlatıcı kenarları daire, squircle ya da yuvarlak kare olarak kırpabilir.</p>\n<p>192 piksellik simge ayrıca yükleme istemi ve bazı cihazların uygulama çekmecesindeki site için kullanılır. Küçültülmüş bir logo gibi değil, uygulama simgesi gibi görünmesi gerekir: belirgin, ortalanmış ve bir bakışta okunaklı.</p>\n<p>Apple simgesinden farklı olarak Android simgesi şeffaflık kullanabilir ama katı bir arka plan yine de en güvenli seçimdir. Katı bir dolgu simgenin her başlatıcıda ve duvar kâğıdında aynı görünmesini garantilerken, şeffaf bir marka yoğun bir arka planla çatışabilir.</p>\n<h2 id=\"the-512-pixel-android-icon\">512 piksellik Android simgesi</h2>\n<p>512'ye 512 piksel, Android karşılama ekranı ve yükleme istemi için kullanılan paketin en büyük boyutudur. Bir kullanıcı kurulu web uygulamanı açtığında sayfa yüklenirken bu simge karşılama ekranında görünür.</p>\n<p>Bu boyutta kaynak görüntünün her arızası görünür. 512 piksele gerilmiş düşük çözünürlüklü bir logo yumuşak görünür ve sıkıştırma bozulmaları olan bir JPEG onları gizlemeden gösterir. Bu boyut küçük bir kaynak dosyayı en çok cezalandıran boyuttur.</p>\n<p>En az 512 piksellik bir kaynak görüntüyle ya da SVG ile başla; böylece en büyük simge en küçük kadar keskin görünür. Vektör görüntü burada idealdir, çünkü 512'ye hiçbir kayıp olmadan ölçeklenir.</p>\n<p>512 piksellik simge ayrıca birçok site oluşturucunun panelde site simgesi ayarlarken istediği dosyadır. Bu PNG'yi yüklemek oluşturucuya ihtiyaçlarına göre yeniden boyutlandırması için büyük ve temiz bir görüntü verir.</p>\n<h2 id=\"how-the-ico-container-works\">ICO kapsayıcısı nasıl çalışır?</h2>\n<p>ICO biçimi, tek dosyada farklı boyutlarda birkaç görüntü saklayan bir kapsayıcıdır. Tipik bir favicon.ico, 16, 32, 48 ve bazen 64 piksellik sürümleri içerir; her biri kapsayıcının içinde kendi görüntüsü olarak saklanır.</p>\n<p>Bir tarayıcı simgeye ihtiyaç duyduğunda ICO dosyasını açar, mevcut boyutlara bakar ve ihtiyaç duyduğuna en yakın olanı seçer. Bu yüzden tek bir dosya ayrı indirmeler olmadan sekmeye, yer imi menüsüne ve masaüstü kısayoluna hizmet edebilir.</p>\n<p>Oluşturucunun ürettiği ICO dosyası gerçek çok kareli ikili bir ICO dosyasıdır. Bu fark önemlidir, çünkü ICO uzantılı yeniden adlandırılmış bir PNG bazı tarayıcıları kandırır ama diğerlerinde başarısız olur ve biçimi doğrulayan araçlarda tamamen başarısız olur.</p>\n<p>Modern tarayıcılar PNG favicon'u da doğrudan kullanabilir ve paket bu yüzden PNG dosyalarını içerir. ICO dosyası uzun geçmişi nedeniyle varsayılan olmaya devam eder: tarayıcılar parça olmasa bile sitenin kökünde favicon.ico ister.</p>\n<h2 id=\"which-size-does-what\">Hangi boyut ne yapar: hızlı harita</h2>\n<p>Sekme simgesi 16 piksel, retina için 32'dir. Masaüstü kısayolları ve sabitlemeler 48 piksel kullanır. Daha büyük yer imi karoları ve yeni sekme sayfaları 64 ve 96 piksel kullanır.</p>\n<p>Apple ana ekranı 180 piksel, Android ana ekran için 192 ve karşılama ile yükleme istemi için 512 piksel kullanır.</p>\n<p>Her boyut farklı bir görüntüleme mesafesidir. Sekme simgesi birçok sekme arasında bir bakışta görülür, ana ekran simgesi uygulamalar arasında niyetle görülür ve karşılama simgesi sayfa yüklenirken tek başına görülür. Tasarım üç mesafede de işe yaramalıdır.</p>\n<p>Paket her bağlamı beş dosyayla kapsar: ICO kapsayıcısı, Apple Touch PNG, iki Android PNG ve onlara işaret eden manifesto. Tam bir kurulum için başka hiçbir şey gerekmez.</p>\n<p>Bir pakette eksik bir boyut bulursan elle eklemek yerine yeniden oluştur. Elle eklenen bir dosya yanlış boyut ya da biçim getirebilirken, yeniden oluşturulmuş bir paket her boyutu aynı kaynak görüntüyle tutarlı tutar.</p>\n<h2 id=\"designing-for-every-size\">Her boyut için tasarım</h2>\n<p>Önce en küçük boyut için tasarla. Marka 16 pikselde okunuyorsa tüm büyük boyutlarda okunur, çünkü büyük boyutlar yalnızca alan ve keskinlik ekler. Markanın anlaşılması için 180 piksel gerekiyorsa en çok görüldüğü sekmede başarısız olur.</p>\n<p>Tek bir belirgin biçim, bir ya da iki renk ve güçlü bir kontrast kullan. Marka renginde katı bir arka plan üzerinde tek bir baş harf, var olan en güvenilir favicon tasarımıdır. Beş renkli ayrıntılı bir çizim en az güvenilir olanıdır.</p>\n<p>Markayı yayımlamadan önce 16, 180 ve 512 pikselde dene. Bu üç boyut sekmeyi, ana ekranı ve karşılama ekranını temsil eder. Tasarım üçünden de sağ çıkarsa ara boyutlar kendiliğinden çözülür.</p>\n<p>Bir logo yeterince basitleştirilemediğinde tüm logo yerine onun bir ayrıntısını kullan. Logonun bir sembolü, tek harfi ya da en tanınabilir biçimi genellikle kareye sıkıştırılmış tam logodan daha iyi bir favicon verir.</p>\n<h2 id=\"checking-your-pack\">Paketini denetleme</h2>\n<p>Oluşturduktan sonra ZIP'i aç ve ICO dosyasının, Apple Touch PNG'sinin, 192 ve 512 piksellik Android PNG'lerinin ve manifestonun bulunduğunu doğrula. Eksik bir dosya genellikle kesintiye uğramış bir indirme demektir; bu yüzden bir şey eksikse yeniden oluştur.</p>\n<p>Paketi sitene kur ve sonra sekme simgesini, yer imi simgesini ve gerçek bir telefondaki ana ekran simgesini incele. Her inceleme farklı bir boyutu dener ve birlikte 16'dan 512 piksele tüm aralığı kapsarlar.</p>\n<p>Eski simge görünmeye devam ederse tarayıcı önbelleğini temizle ve yeni bir ziyaretçinin gördüğünü görmek için gizli bir pencerede dene. Gizli pencerenin önbelleği boştur; bu yüzden güncel dosyaları gösterir, kaydedilmiş bir kopyayı değil.</p>\n<p>Bir boyut kötü görünürken diğerleri iyi görünüyorsa kaynak görüntü genellikle nedendir. Düşük çözünürlüklü bir görüntü 512 pikselde başarısız olur ve ayrıntılı bir görüntü 16'da başarısız olur. Tek bir çıktı dosyasını düzenlemek yerine daha iyi bir kaynak görüntüden yeniden oluştur.</p>\n<h2 id=\"quick-reference\">Hızlı başvuru: favicon boyutları bir bakışta</h2>\n<p>Sekme: 16 piksel, retina 32. Masaüstü kısayolu: 48. Yer imi karoları: 64 ve 96. Apple ana ekranı: 180. Android ana ekranı: 192. Android karşılama ve yükleme: 512. ICO dosyası küçük boyutları saklar, PNG dosyaları büyükleri saklar ve manifesto Android simgelerini listeler.</p>\n<p>Önce 16 piksel için tasarla, en az 512 piksellik bir kaynak görüntü ya da SVG ile başla ve Apple simgesine katı bir arka plan ver. İşi bitmiş saymadan önce sekmeyi, yer imini ve ana ekranı dene.</p>\n<p>Tam kılavuz için <a href=\"/tr/blog/favicon-olusturucu-rehberi\">Favicon Oluşturucu: Tam Kılavuz</a> yazısını oku ve adım adım için <a href=\"/tr/blog/favicon-nasil-olusturulur\">Favicon Nasıl Oluşturulur?</a> yazısını oku. Paketini <a href=\"/tr/favicon-olusturucu\">favicon oluşturucu</a> ile oluştur.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"İhtiyacım olan en küçük favicon boyutu nedir?","answer":"16'ya 16 piksel, tarayıcı sekmesi için kullanılan en küçük boyuttur. Tasarlaması da en zor olanıdır, çünkü yalnızca en belirgin biçimler o boyutta ayakta kalır. Bir paket indirmeden önce her zaman 16 piksellik önizlemeyi inceleyin."},{"question":"Minik bir sekme favicon'u için neden 512'ye 512 simgeye ihtiyacım var?","answer":"512 piksellik simge sekme için değildir. Android onu karşılama ekranı ve yükleme istemi için kullanır; burada simge büyük gösterilir. Onu içermeyen bir paket, sekme simgesi iyi çalışsa bile Android'de gerilmiş ya da eksik bir simge gösterir."},{"question":"PNG favicon yeterli mi yoksa ICO dosyası gerekir mi?","answer":"PNG modern tarayıcılarda çalışır ama ICO dosyası varsayılan olmaya devam eder: tarayıcılar parça olmasa bile sitenin kökünde favicon.ico ister ve ICO kapsayıcısı tek dosyada birkaç boyut saklar. Tam bir paket ikisini de içerir; bu yüzden tüm tarayıcılar ve bağlamlar kapsanır."},{"question":"Favicon için kaynak logom ne boyutta olmalıdır?","answer":"En az 512'ye 512 piksel ya da sabit çözünürlüğü olmayan bir SVG. Paketin en büyük simgesi 512 pikseldir; bu yüzden daha küçük bir görüntü gerilir ve yumuşak görünür. Büyük bir görüntü ya da vektör dosyası tüm boyutları keskin tutar."},{"question":"Apple Touch Icon neden katı bir arka plan ister?","answer":"Apple ana ekran simgesindeki şeffaf bölgeleri siyahla doldurur; bu oluşturma hatası gibi görünür. Marka renginde katı bir arka plan siyah köşeleri tamamen önler ve simgenin bilinçli yapılmış bir uygulama simgesi gibi görünmesini sağlar."},{"question":"Tüm tarayıcılar aynı favicon boyutlarını mı kullanır?","answer":"Çoğunlukla ama tam olarak değil. Tüm tarayıcılar sekmeler için 16 ve 32 piksel kullanırken, Apple ve Android'in her birinin kendi ana ekran boyutları vardır. Tam bir paket paylaşılan boyutları ve platforma özgü boyutları kapsar; bu yüzden her tarayıcıyı ayrı ayrı izlemen gerekmez."}];
